/**
 * Gallai path decomposition — exhaustive check over nonisomorphic connected
 * graphs for n ≤ N (default 8), generated by nauty `geng -c`.
 *
 * For each graph: either certify path_number ≤ ceil(n/2) via a verified path
 * decomposition, or emit a counterexample certificate.
 *
 * Requires: `geng` on PATH (Homebrew: nauty).
 *
 * Run:
 *   bun research/gallai-unlabeled.ts
 *   bun research/gallai-unlabeled.ts --n 8
 *   bun research/gallai-unlabeled.ts --n 7 --sanity-labeled
 *
 * Exit 0 only if every connected graph checked satisfies the bound.
 */

import {
  allPairs,
  buildAdj,
  degrees,
  edgeCount,
  gallaiBound,
  parseGraph6,
  pathLowerBound,
  pathNumberAtMost,
  exactPathNumber,
  verifyDecomposition,
  starTightCertificate,
  completeMask,
  pairIndex,
} from "./gallai-lib.ts";

const args = process.argv.slice(2);
function flag(name: string): boolean {
  return args.includes(`--${name}`);
}
function opt(name: string, fallback: string): string {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1]! : fallback;
}

const MAX_N = Number(opt("n", "9"));
const WRITE_ARTIFACTS = !flag("no-artifacts");
const SANITY_LABELED = flag("sanity-labeled");
const RUN_DIR =
  opt(
    "run-dir",
    process.env.MATHSMASHER_RUN_DIR ??
      "/Users/mewc/.mathsmasher/runs/2026-07-24T01-08-34-gallai-paths-v1",
  );

if (!Number.isInteger(MAX_N) || MAX_N < 1 || MAX_N > 9) {
  throw new Error(`--n must be integer in 1..9, got ${MAX_N}`);
}

// OEIS A001349: number of connected unlabeled graphs on n nodes
const EXPECTED_CONNECTED_UNLABELED: Record<number, number> = {
  1: 1,
  2: 1,
  3: 2,
  4: 6,
  5: 21,
  6: 112,
  7: 853,
  8: 11117,
  9: 261080,
};

type TightEx = {
  n: number;
  m: number;
  degrees: number[];
  edges: Array<[number, number]>;
  paths: number[][];
  pathNumber: number;
  graph6: string;
};

type NResult = {
  n: number;
  bound: number;
  graphs: number;
  verified: number;
  tight: number;
  maxPathNumber: number;
  lbAlreadyBound: number; // graphs where combinatorial lb ≥ bound (hence = bound on success)
  counterexamples: Array<{
    graph6: string;
    pathNumber: number;
    paths: number[][];
    edges: Array<[number, number]>;
  }>;
  tightExamples: TightEx[];
  ms: number;
  hardCases: number; // needed exact search (greedy > bound)
};

async function ensureGeng(): Promise<string> {
  const which = Bun.which("geng");
  if (which) return which;
  throw new Error(
    "geng not found on PATH. Install nauty (e.g. `brew install nauty`).",
  );
}

async function gengConnected(n: number): Promise<string[]> {
  if (n === 1) return ["@"]; // graph6 for single vertex
  const geng = await ensureGeng();
  // -c connected, -q quiet (no counts on stderr noise — actually -q suppresses aux)
  const proc = Bun.spawn([geng, "-c", "-q", String(n)], {
    stdout: "pipe",
    stderr: "pipe",
  });
  const out = await new Response(proc.stdout).text();
  const err = await new Response(proc.stderr).text();
  const code = await proc.exited;
  if (code !== 0) {
    throw new Error(`geng -c ${n} failed (exit ${code}): ${err}`);
  }
  return out
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0);
}

function runForN(n: number, graphs: string[]): NResult {
  const t0 = performance.now();
  const pairs = allPairs(n);
  const bound = gallaiBound(n);

  let verified = 0;
  let tight = 0;
  let maxPathNumber = 0;
  let lbAlreadyBound = 0;
  let hardCases = 0;
  const counterexamples: NResult["counterexamples"] = [];
  const tightExamples: TightEx[] = [];

  let i = 0;
  for (const g6 of graphs) {
    i++;
    const { n: gn, edgeMask, edges } = parseGraph6(g6);
    if (gn !== n) throw new Error(`graph6 n=${gn} expected ${n}: ${g6}`);

    const adj = buildAdj(n, edgeMask, pairs);
    const deg = degrees(adj);
    const m = edgeCount(edgeMask);
    const lb = pathLowerBound(deg, m, n);

    if (lb > bound) {
      // combinatorial obstruction — would be a counterexample without search
      counterexamples.push({
        graph6: g6,
        pathNumber: lb,
        paths: [],
        edges,
      });
      maxPathNumber = Math.max(maxPathNumber, lb);
      continue;
    }

    const within = pathNumberAtMost(n, edgeMask, pairs, bound);
    if (!within.ok) {
      hardCases++;
      const full = exactPathNumber(
        n,
        edgeMask,
        pairs,
        Math.max(bound + 3, lb + 3, m),
      );
      counterexamples.push({
        graph6: g6,
        pathNumber: full.num,
        paths: full.paths,
        edges,
      });
      maxPathNumber = Math.max(maxPathNumber, full.num);
      continue;
    }

    // If greedy already ≤ bound, within is fast; count as hard if we had to
    // go past greedy (num may still be from greedy). Track via lb vs result.
    verified++;
    let pNum = within.num;
    let pPaths = within.paths;
    let isTight = false;

    if (lb === bound) {
      lbAlreadyBound++;
      isTight = true;
      pNum = bound;
    } else if (within.num === bound) {
      // decomp of size bound; check if smaller exists
      const better = pathNumberAtMost(n, edgeMask, pairs, bound - 1);
      if (!better.ok) {
        isTight = true;
        pNum = bound;
      } else {
        pNum = better.num;
        pPaths = better.paths;
      }
    } else {
      // within.num < bound ⇒ not tight
      pNum = within.num;
    }

    maxPathNumber = Math.max(maxPathNumber, pNum);

    if (isTight) {
      tight++;
      if (tightExamples.length < 40) {
        tightExamples.push({
          n,
          m,
          degrees: deg,
          edges,
          paths: pPaths,
          pathNumber: pNum,
          graph6: g6,
        });
      }
    }

    if (n >= 8 && i % 1000 === 0) {
      const elapsed = performance.now() - t0;
      process.stdout.write(
        `\n    … ${i}/${graphs.length} verified=${verified} tight=${tight} hard≈${hardCases} cex=${counterexamples.length} ${elapsed.toFixed(0)}ms`,
      );
    }
  }

  return {
    n,
    bound,
    graphs: graphs.length,
    verified,
    tight,
    maxPathNumber,
    lbAlreadyBound,
    counterexamples,
    tightExamples,
    ms: performance.now() - t0,
    hardCases,
  };
}

// ── labeled sanity (small n) ───────────────────────────────────────────────

function labeledConnectedCount(n: number): number {
  if (n === 1) return 1;
  const pairs = allPairs(n);
  // number masks only for n≤7 (C(7,2)=21 < 31)
  if (pairs.length > 30) throw new Error("labeled sanity only for n≤7");
  const total = 1 << pairs.length;
  let c = 0;
  for (let mask = 1; mask < total; mask++) {
    const adj = buildAdj(n, BigInt(mask), pairs);
    const seen = new Uint8Array(n);
    let start = -1;
    for (let u = 0; u < n; u++) {
      if (adj[u]!.length) {
        start = u;
        break;
      }
    }
    if (start < 0) continue;
    const stack = [start];
    seen[start] = 1;
    let vis = 1;
    while (stack.length) {
      const u = stack.pop()!;
      for (const v of adj[u]!) {
        if (!seen[v]) {
          seen[v] = 1;
          vis++;
          stack.push(v);
        }
      }
    }
    if (vis === n) c++;
  }
  return c;
}

// ── main ───────────────────────────────────────────────────────────────────

console.log("Gallai path decomposition — nonisomorphic exhaustive engine");
console.log(`Claim: every connected G on n verts has path_number ≤ ceil(n/2).`);
console.log(`Universe: nauty geng -c for n = 1..${MAX_N}\n`);

await ensureGeng();

const results: NResult[] = [];
let globalFail = false;

for (let n = 1; n <= MAX_N; n++) {
  process.stdout.write(`n=${n} (bound ${gallaiBound(n)}) generating… `);
  const graphs = await gengConnected(n);
  const exp = EXPECTED_CONNECTED_UNLABELED[n];
  if (exp !== undefined && graphs.length !== exp) {
    console.log(
      `COUNT MISMATCH: geng produced ${graphs.length}, OEIS A001349 expects ${exp}`,
    );
    globalFail = true;
  } else {
    process.stdout.write(`${graphs.length} graphs … `);
  }

  const r = runForN(n, graphs);
  results.push(r);

  if (r.counterexamples.length === 0) {
    console.log(
      `OK verified=${r.verified} tight=${r.tight} max_p=${r.maxPathNumber} lb=bound:${r.lbAlreadyBound} (${r.ms.toFixed(0)}ms)`,
    );
  } else {
    globalFail = true;
    console.log(`FAIL cex=${r.counterexamples.length}`);
    for (const c of r.counterexamples.slice(0, 5)) {
      console.log(
        `  ${c.graph6} p=${c.pathNumber} edges=${JSON.stringify(c.edges)}`,
      );
    }
  }
}

// Star family
console.log("\n── Tight family: stars K_{1,n-1} ──");
for (let n = 2; n <= Math.max(MAX_N, 10); n++) {
  const s = starTightCertificate(n);
  const pairs = allPairs(n);
  let mask = 0n;
  for (const [u, v] of s.edges) mask |= 1n << BigInt(pairIndex(u, v, n));
  const v = verifyDecomposition(n, mask, pairs, s.paths);
  if (!v.ok) throw new Error(`star n=${n}: ${v.reason}`);
  const lb = Math.ceil((n - 1) / 2);
  if (s.pathNumber !== lb) {
    throw new Error(`star n=${n}: construction ${s.pathNumber} vs lb ${lb}`);
  }
  console.log(
    `  n=${n}: p=${s.pathNumber} bound=${s.bound} tight=${s.tight}${s.tight ? " ★" : ""}`,
  );
}

// Completes
console.log("\n── Complete graphs K_n ──");
for (let n = 2; n <= MAX_N; n++) {
  const pairs = allPairs(n);
  const mask = completeMask(n);
  const bound = gallaiBound(n);
  const m = (n * (n - 1)) / 2;
  const lb = Math.ceil(m / (n - 1));
  const r = pathNumberAtMost(n, mask, pairs, bound);
  if (!r.ok || lb !== bound) {
    console.log(`  K_${n}: FAIL r.ok=${r.ok} lb=${lb} bound=${bound} num=${r.num}`);
    globalFail = true;
  } else {
    console.log(`  K_${n}: p=${bound} = ceil(m/(n-1)) tight ★`);
  }
}

// Sample tight
console.log("\n── Sample tight (unlabeled) ──");
for (const r of results) {
  if (r.n < 2) continue;
  console.log(`n=${r.n}: ${r.tight} tight of ${r.graphs}`);
  for (const t of r.tightExamples.slice(0, 6)) {
    console.log(
      `  m=${t.m} deg=[${t.degrees.join(",")}] g6=${t.graph6} p=${t.pathNumber}`,
    );
  }
}

if (SANITY_LABELED && MAX_N >= 6) {
  console.log("\n── Labeled count sanity (n≤6) ──");
  const EXP: Record<number, number> = {
    1: 1,
    2: 1,
    3: 4,
    4: 38,
    5: 728,
    6: 26704,
  };
  for (let n = 1; n <= Math.min(6, MAX_N); n++) {
    const c = labeledConnectedCount(n);
    const ok = c === EXP[n];
    console.log(`  n=${n}: labeled connected=${c} expected=${EXP[n]} ${ok ? "OK" : "FAIL"}`);
    if (!ok) globalFail = true;
  }
}

// OEIS table check
console.log("\n── Unlabeled connected counts (OEIS A001349) ──");
for (const r of results) {
  const exp = EXPECTED_CONNECTED_UNLABELED[r.n];
  if (exp === undefined) {
    console.log(`  n=${r.n}: ${r.graphs} (no table)`);
  } else if (r.graphs === exp) {
    console.log(`  n=${r.n}: ${r.graphs} matches A001349`);
  } else {
    console.log(`  n=${r.n}: ${r.graphs} ≠ ${exp} FAIL`);
    globalFail = true;
  }
}

if (WRITE_ARTIFACTS) {
  const artDir = `${RUN_DIR}/artifacts`;
  const summary = {
    claim:
      "Every connected simple graph on n vertices has edge-path-number ≤ ceil(n/2).",
    method:
      "Exhaustive over nonisomorphic connected graphs from nauty geng -c; exact path_number search with certified decompositions.",
    maxN: MAX_N,
    verdict: globalFail
      ? "counterexample_or_mismatch"
      : `holds_for_all_connected_unlabeled_n_le_${MAX_N}`,
    note:
      "Isomorphism-class coverage: if p(G)≤B for one labeled representative of each class, then p≤B for all labeled graphs (path_number is isomorphism-invariant). Combined with turn-1 full labeled check for n≤7, n=8 is newly covered here.",
    results: results.map((r) => ({
      n: r.n,
      bound: r.bound,
      unlabeledConnected: r.graphs,
      verified: r.verified,
      tight: r.tight,
      maxPathNumber: r.maxPathNumber,
      lbEqualsBound: r.lbAlreadyBound,
      counterexamples: r.counterexamples.length,
      ms: Math.round(r.ms),
    })),
    tightSamples: results.flatMap((r) =>
      r.tightExamples.slice(0, 12).map((t) => ({
        n: t.n,
        m: t.m,
        degrees: t.degrees,
        edges: t.edges,
        paths: t.paths,
        pathNumber: t.pathNumber,
        graph6: t.graph6,
      })),
    ),
  };
  await Bun.write(
    `${artDir}/gallai-unlabeled-summary.json`,
    JSON.stringify(summary, null, 2),
  );
  console.log(`\nWrote ${artDir}/gallai-unlabeled-summary.json`);
}

console.log("\n── Verdict ──");
if (globalFail) {
  console.log("COUNTEREXAMPLE or count mismatch — see above.");
  process.exit(1);
}
console.log(
  `Gallai bound holds for every connected simple graph on n ≤ ${MAX_N} vertices`,
);
console.log(
  `(exhaustive over nonisomorphic classes via geng -c; certificates verified).`,
);
console.log("Finite verification, not a general proof. Conjecture remains open.");
process.exit(0);
